{
  "name": "CTypes库仪器驱动基类",
  "name_en": "ctypes Library Instrument Driver Base",
  "manufacturer": "",
  "description": "这是一个通过动态链接库（如 DLL）与实验仪器通信的通用软件驱动基类。本身未对应到某一特定物理仪器，而是用于为各类提供厂商库接口的实验设备建立调用接口与数据类型映射。",
  "description_en": "This is a generic software driver base for communicating with laboratory instruments through a dynamic library such as a DLL. It does not correspond to a specific physical instrument by itself; instead, it is used to build call interfaces and data type mappings for devices that provide vendor libraries.",
  "actions": [
    {
      "action_name": "auto-argtypes",
      "description": "定义库函数的参数类型。",
      "description_en": "Define the argument types of a library function."
    },
    {
      "action_name": "auto-restype",
      "description": "定义库函数的返回类型。",
      "description_en": "Define the return type of a library function."
    },
    {
      "action_name": "auto-value",
      "description": "获取封装返回对象中的值。",
      "description_en": "Get the value contained in a wrapped return object."
    }
  ],
  "tag_hints": [
    "ctypes library binding",
    "DLL instrument communication",
    "vendor library interface",
    "function signature mapping",
    "return type conversion"
  ]
}

